import sys

def solve():
    s = sys.stdin.readline().strip()
    friends = ["Danil", "Olya", "Slava", "Ann", "Nikita"]

    total_count = 0
    for friend in friends:
        count = 0
        start = 0
        while True:
            idx = s.find(friend, start)
            if idx == -1:
                break
            count += 1
            start = idx + len(friend)

        total_count += count

    if total_count == 1:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    solve()
